				expect(Time("100:0:0").toBarsBeatsSixteenths()).to.equal(
					"100:0:0"
				);
			});
		});
	});
});

import { getContext } from "../Global.js";
import { ftom } from "./Conversions.js";
import {
	TimeBaseClass,
	TimeBaseUnit,
	TimeExpression,
	TimeValue,
} from "./TimeBase.js";
import {
	BarsBeatsSixteenths,
	MidiNote,
	Seconds,
	Subdivision,
	Ticks,
	Time,
} from "./Units.js";

/**
 * TimeClass is a primitive type for encoding and decoding Time values.
 * TimeClass can be passed into the parameter of any method which takes time as an argument.
 * @param  val    The time value.
 * @param  units  The units of the value.
 * @example
 * const time = Tone.Time("4n"); // a quarter note
 * @category Unit
 */
export class TimeClass<
	Type extends Seconds | Ticks = Seconds,
	Unit extends string = TimeBaseUnit,
> extends TimeBaseClass<Type, Unit> {
	readonly name: string = "TimeClass";

	protected _getExpressions(): TimeExpression<Type> {
		return Object.assign(super._getExpressions(), {
			now: {
				method: (capture: string): Type => {
					return (this._now() +
						new (this.constructor as typeof TimeClass)(
							this.context,
							capture
						).valueOf()) as Type;
				},
				regexp: /^\+(.+)/,
			},
			quantize: {
				method: (capture: string): Type => {
					const quantTo = new TimeClass(
						this.context,
						capture
					).valueOf();
					return this._secondsToUnits(
						this.context.transport.nextSubdivision(quantTo)
					);
				},
				regexp: /^@(.+)/,
			},
		});
	}

	/**
	 * Quantize the time by the given subdivision. Optionally add a
	 * percentage which will move the time value towards the ideal
	 * quantized value by that percentage.
	 * @param  subdiv    The subdivision to quantize to
	 * @param  percent  Move the time value towards the quantized value by a percentage.
	 * @example
	 * Tone.Time(21).quantize(2); // returns 22
	 * Tone.Time(0.6).quantize("4n", 0.5); // returns 0.55
	 */
	quantize(subdiv: Time, percent = 1): Type {
		const subdivision = new (this.constructor as typeof TimeClass)(
			this.context,
			subdiv
		).valueOf();
		const value = this.valueOf();
		const multiple = Math.round(value / subdivision);
		const ideal = multiple * subdivision;
		const diff = ideal - value;
		return (value + diff * percent) as Type;
	}

	//-------------------------------------
	// CONVERSIONS
	//-------------------------------------
	/**
	 * Convert a Time to Notation. The notation values are will be the
	 * closest representation between 1m to 128th note.
	 * @return {Notation}
	 * @example
	 * // if the Transport is at 120bpm:
	 * Tone.Time(2).toNotation(); // returns "1m"
	 */
	toNotation(): Subdivision {
		const time = this.toSeconds();
		const testNotations: Subdivision[] = ["1m"];
		for (let power = 1; power < 9; power++) {
			const subdiv = Math.pow(2, power);
			testNotations.push((subdiv + "n.") as Subdivision);
			testNotations.push((subdiv + "n") as Subdivision);
			testNotations.push((subdiv + "t") as Subdivision);
		}
		testNotations.push("0");
		// find the closets notation representation
		let closest = testNotations[0];
		let closestSeconds = new TimeClass(
			this.context,
			testNotations[0]
		).toSeconds();
		testNotations.forEach((notation) => {
			const notationSeconds = new TimeClass(
				this.context,
				notation
			).toSeconds();
			if (
				Math.abs(notationSeconds - time) <
				Math.abs(closestSeconds - time)
			) {
				closest = notation;
				closestSeconds = notationSeconds;
			}
		});
		return closest;
	}

	/**
	 * Return the time encoded as Bars:Beats:Sixteenths.
	 */
	toBarsBeatsSixteenths(): BarsBeatsSixteenths {
		const quarterTime = this._beatsToUnits(1);
		let quarters = this.valueOf() / quarterTime;
		quarters = parseFloat(quarters.toFixed(4));
		const measures = Math.floor(quarters / this._getTimeSignature());
		let sixteenths = (quarters % 1) * 4;
		quarters = Math.floor(quarters) % this._getTimeSignature();
		const sixteenthString = sixteenths.toString();
		if (sixteenthString.length > 3) {
			// the additional parseFloat removes insignificant trailing zeroes
			sixteenths = parseFloat(parseFloat(sixteenthString).toFixed(3));
		}
		const progress = [measures, quarters, sixteenths];
		return progress.join(":") as BarsBeatsSixteenths;
	}

	/**
	 * Return the time in ticks.
	 */
	toTicks(): Ticks {
		const quarterTime = this._beatsToUnits(1);
		const quarters = this.valueOf() / quarterTime;
		return quarters * this._getPPQ();
	}

	/**
	 * Return the time in seconds.
	 */
	toSeconds(): Seconds {
		return this.valueOf();
	}

	/**
	 * Return the value as a midi note.
	 */
	toMidi(): MidiNote {
		return ftom(this.toFrequency());
	}

	protected _now(): Type {
		return this.context.now() as Type;
	}
}

/**
 * Create a TimeClass from a time string or number. The time is computed against the
 * global Tone.Context. To use a specific context, use {@link TimeClass}
 * @param value A value which represents time
 * @param units The value's units if they can't be inferred by the value.
 * @category Unit
 * @example
 * const time = Tone.Time("4n").toSeconds();
 * console.log(time);
 * @example
 * const note = Tone.Time(1).toNotation();
 * console.log(note);
 * @example
 * const freq = Tone.Time(0.5).toFrequency();
 * console.log(freq);
 */
export function Time(
	value?: TimeValue,
	units?: TimeBaseUnit
): TimeClass<Seconds> {
	return new TimeClass(getContext(), value, units);
}

import { BaseContext } from "../context/BaseContext.js";
import { Tone } from "../Tone.js";
import { isDefined, isObject, isString, isUndef } from "../util/TypeCheck.js";
import {
	BPM,
	Hertz,
	MidiNote,
	Milliseconds,
	Samples,
	Seconds,
	Ticks,
	Time,
} from "./Units.js";

export type TimeValue = Time | TimeBaseClass<any, any>;

/**
 * The units that the TimeBase can accept. extended by other classes
 */
export type TimeBaseUnit =
	| "s"
	| "n"
	| "t"
	| "m"
	| "i"
	| "hz"
	| "tr"
	| "samples"
	| "number";

export interface TypeFunction {
	regexp: RegExp;
	method: (
		this: TimeBaseClass<any, any>,
		value: string,
		...args: string[]
	) => number;
}

export interface TimeExpression<Type extends number> {
	[key: string]: {
		regexp: RegExp;
		method: (
			this: TimeBaseClass<any, any>,
			value: string,
			...args: string[]
		) => Type;
	};
}

/**
 * TimeBase is a flexible encoding of time which can be evaluated to and from a string.
 */
export abstract class TimeBaseClass<
	Type extends number,
	Unit extends string,
> extends Tone {
	readonly context: BaseContext;

	/**
	 * The value of the units
	 */
	protected _val?: TimeValue;

	/**
	 * The units of time
	 */
	protected _units?: Unit;

	/**
	 * All of the conversion expressions
	 */
	protected _expressions: TimeExpression<Type>;

	/**
	 * The default units
	 */
	readonly defaultUnits: Unit = "s" as Unit;

	/**
	 * @param context The context associated with the time value. Used to compute
	 * Transport and context-relative timing.
	 * @param  value  The time value as a number, string or object
	 * @param  units  Unit values
	 */
	constructor(context: BaseContext, value?: TimeValue, units?: Unit) {
		super();

		this._val = value;
		this._units = units;
		this.context = context;
		this._expressions = this._getExpressions();
	}

	/**
	 * All of the time encoding expressions
	 */
	protected _getExpressions(): TimeExpression<Type> {
		return {
			hz: {
				method: (value) => {
					return this._frequencyToUnits(parseFloat(value));
				},
				regexp: /^(\d+(?:\.\d+)?)hz$/i,
			},
			i: {
				method: (value) => {
					return this._ticksToUnits(parseInt(value, 10));
				},
				regexp: /^(\d+)i$/i,
			},
			m: {
				method: (value) => {
					return this._beatsToUnits(
						parseInt(value, 10) * this._getTimeSignature()
					);
				},
				regexp: /^(\d+)m$/i,
			},
			n: {
				method: (value: string, dot: string) => {
					const numericValue = parseInt(value, 10);
					const scalar = dot === "." ? 1.5 : 1;
					if (numericValue === 1) {
						return (this._beatsToUnits(this._getTimeSignature()) *
							scalar) as Type;
					} else {
						return (this._beatsToUnits(4 / numericValue) *
							scalar) as Type;
					}
				},
				regexp: /^(\d+)n(\.?)$/i,
			},
			number: {
				method: (value) => {
					return this._expressions[this.defaultUnits].method.call(
						this,
						value
					);
				},
				regexp: /^(\d+(?:\.\d+)?)$/,
			},
			s: {
				method: (value): Type => {
					return this._secondsToUnits(parseFloat(value));
				},
				regexp: /^(\d+(?:\.\d+)?)s$/,
			},
			samples: {
				method: (value) => {
					return (parseInt(value, 10) /
						this.context.sampleRate) as Type;
				},
				regexp: /^(\d+)samples$/,
			},
			t: {
				method: (value) => {
					const numericValue = parseInt(value, 10);
					return this._beatsToUnits(
						8 / (Math.floor(numericValue) * 3)
					);
				},
				regexp: /^(\d+)t$/i,
			},
			tr: {
				method: (m: string, q: string, s: string) => {
					let total = 0;
					if (m && m !== "0") {
						total += this._beatsToUnits(
							this._getTimeSignature() * parseFloat(m)
						);
					}
					if (q && q !== "0") {
						total += this._beatsToUnits(parseFloat(q));
					}
					if (s && s !== "0") {
						total += this._beatsToUnits(parseFloat(s) / 4);
					}
					return total as Type;
				},
				regexp: /^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?):?(\d+(?:\.\d+)?)?$/,
			},
		};
	}

	//-------------------------------------
	// 	VALUE OF
	//-------------------------------------

	/**
	 * Evaluate the time value. Returns the time in seconds.
	 */
	valueOf(): Type {
		if (this._val instanceof TimeBaseClass) {
			this.fromType(this._val);
		}
		if (isUndef(this._val)) {
			return this._noArg();
		} else if (isString(this._val) && isUndef(this._units)) {
			for (const units in this._expressions) {
				if (this._expressions[units].regexp.test(this._val.trim())) {
					this._units = units as Unit;
					break;
				}
			}
		} else if (isObject(this._val)) {
			let total = 0;
			for (const typeName in this._val) {
				if (isDefined(this._val[typeName])) {
					const quantity = this._val[typeName];
					const time =
						// @ts-ignore
						new this.constructor(this.context, typeName).valueOf() *
						quantity;
					total += time;
				}
			}
			return total as Type;
		}
		if (isDefined(this._units)) {
			const expr = this._expressions[this._units];
			const matching = this._val.toString().trim().match(expr.regexp);
			if (matching) {
				return expr.method.apply(
					this,
					matching.slice(1) as [string, ...string[]]
				);
			} else {
				return expr.method.call(this, String(this._val));
			}
		} else if (isString(this._val)) {
			return parseFloat(this._val) as Type;
		} else {
			return this._val as Type;
		}
	}

	//-------------------------------------
	// 	UNIT CONVERSIONS
	//-------------------------------------

	/**
	 * Returns the value of a frequency in the current units
	 */
	protected _frequencyToUnits(freq: Hertz): Type {
		return (1 / freq) as Type;
	}

	/**
	 * Return the value of the beats in the current units
	 */
	protected _beatsToUnits(beats: number): Type {
		return ((60 / this._getBpm()) * beats) as Type;
	}

	/**
	 * Returns the value of a second in the current units
	 */
	protected _secondsToUnits(seconds: Seconds): Type {
		return seconds as Type;
	}

	/**
	 * Returns the value of a tick in the current time units
	 */
	protected _ticksToUnits(ticks: Ticks): Type {
		return ((ticks * this._beatsToUnits(1)) / this._getPPQ()) as Type;
	}

	/**
	 * With no arguments, return 'now'
	 */
	protected _noArg(): Type {
		return this._now();
	}

	//-------------------------------------
	// 	TEMPO CONVERSIONS
	//-------------------------------------

	/**
	 * Return the bpm
	 */
	protected _getBpm(): BPM {
		return this.context.transport.bpm.value;
	}

	/**
	 * Return the timeSignature
	 */
	protected _getTimeSignature(): number {
		return this.context.transport.timeSignature as number;
	}

	/**
	 * Return the PPQ or 192 if Transport is not available
	 */
	protected _getPPQ(): number {
		return this.context.transport.PPQ;
	}

	/**
	 * Return the current time in whichever context is relevant
	 */
	protected abstract _now(): Type;

	//-------------------------------------
	// 	CONVERSION INTERFACE
	//-------------------------------------

	/**
	 * Coerce a time type into this units type.
	 * @param type Any time type units
	 */
	fromType(type: TimeBaseClass<any, any>): this {
		this._units = undefined;
		switch (this.defaultUnits) {
			case "s":
				this._val = type.toSeconds();
				break;
			case "i":
				this._val = type.toTicks();
				break;
			case "hz":
				this._val = type.toFrequency();
				break;
			case "midi":
				this._val = type.toMidi();
				break;
		}
		return this;
	}

	/**
	 * Return the value in seconds
	 */
	abstract toSeconds(): Seconds;

	/**
	 * Return the value as a Midi note
	 */
	abstract toMidi(): MidiNote;

	/**
	 * Convert the value into ticks
	 */
	abstract toTicks(): Ticks;

	/**
	 * Return the value in hertz
	 */
	toFrequency(): Hertz {
		return 1 / this.toSeconds();
	}

	/**
	 * Return the time in samples
	 */
	toSamples(): Samples {
		return this.toSeconds() * this.context.sampleRate;
	}

	/**
	 * Return the time in milliseconds.
	 */
	toMilliseconds(): Milliseconds {
		return this.toSeconds() * 1000;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../../test/helper/Basic.js";
import { atTime, Offline } from "../../../test/helper/Offline.js";
import { getContext } from "../Global.js";
import { Frequency } from "./Frequency.js";
import { Ticks } from "./Ticks.js";
import { Time } from "./Time.js";
import { TransportTime, TransportTimeClass } from "./TransportTime.js";

describe("TransportTimeClass", () => {
	BasicTests(TransportTime);

	context("Constructor", () => {
		it("can be made with or without 'new'", () => {
			const t0 = TransportTime();
			expect(t0).to.be.instanceOf(TransportTimeClass);
			t0.dispose();
			const t1 = new TransportTimeClass(getContext());
			expect(t1).to.be.instanceOf(TransportTimeClass);
			t1.dispose();
		});

		it("can pass in a number in the constructor", () => {
			return Offline(() => {
				const time = TransportTime(1);
				expect(time).to.be.instanceOf(TransportTimeClass);
				expect(time.valueOf()).to.equal(1);
				time.dispose();
			});
		});

		it("can pass in a string in the constructor", () => {
			return Offline((context) => {
				const time = TransportTime("1");
				expect(time).to.be.instanceOf(TransportTimeClass);
				expect(time.valueOf()).to.equal(1);
				time.dispose();
			});
		});

		it("can pass in a value and a type", () => {
			return Offline((context) => {
				expect(TransportTime(4, "m").valueOf()).to.equal(8);
			});
		});

		it("with no arguments evaluates to 0 when the transport is stopped", () => {
			return Offline(() => {
				expect(TransportTime().valueOf()).to.equal(0);
			});
		});

		it("with no arguments evaluates to the current ticks when the transport is started", () => {
			return Offline((context) => {
				const transport = context.transport;
				transport.start();
				return atTime(0.29, () => {
					expect(new TransportTimeClass(context).valueOf()).to.equal(
						transport.seconds
					);
					transport.stop();
				});
			}, 0.3);
		});

		it("is evaluated in equations and comparisons using valueOf", () => {
			// @ts-ignore
			expect(TransportTime("1") + 1).to.equal(2);
			// @ts-ignore
			expect(TransportTime("1") + TransportTime("1")).to.equal(2);
			expect(TransportTime("1") > TransportTime(0)).to.be.true;
			expect(+TransportTime("1")).to.equal(1);
		});

		it("can convert from Time", () => {
			expect(TransportTime(Time(2)).valueOf()).to.equal(2);
			expect(TransportTime(Time("4n")).valueOf()).to.equal(0.5);
		});

		it("can convert from Frequency", () => {
			expect(TransportTime(Frequency(2)).valueOf()).to.equal(0.5);
			expect(TransportTime(Frequency("4n")).valueOf()).to.equal(0.5);
		});

		it("can convert from TransportTime", () => {
			expect(TransportTime(TransportTime(2)).valueOf()).to.equal(2);
			expect(TransportTime(TransportTime("4n")).valueOf()).to.equal(0.5);
		});

		it("can convert from Ticks", () => {
			return Offline((context) => {
				const transport = context.transport;
				expect(TransportTime(Ticks(transport.PPQ)).valueOf()).to.equal(
					0.5
				);
				expect(TransportTime(Ticks("4n")).valueOf()).to.equal(0.5);
			});
		});

		it("can convert from an Object", () => {
			return Offline(() => {
				expect(TransportTime({ "4n": 2 }).valueOf()).to.equal(1);
				expect(
					TransportTime({ "1n": 1, "8t": 2 }).valueOf()
				).to.be.closeTo(2.333, 0.01);
			});
		});
	});

	context("Quantizes values", () => {
		it("can quantize values", () => {
			return Offline((context) => {
				expect(
					TransportTime("4t").quantize("4n").valueOf()
				).to.be.closeTo(0.5, 0.01);
			});
		});

		it("can get the next subdivision when the transport is started", () => {
			return Offline((context) => {
				const transport = context.transport;
				transport.start();
				return atTime(0.59, () => {
					expect(
						new TransportTimeClass(context, "@1m").valueOf()
					).to.be.closeTo(2, 0.01);
					expect(
						new TransportTimeClass(context, "@4n").valueOf()
					).to.be.closeTo(1, 0.01);
				});
			}, 0.6);
		});

		it("returns transport time (not AudioContext time)", () => {
			// Address #401
			return Offline((context) => {
				const transport = context.transport;
				transport.start(0.1);
				return atTime(0.69, () => {
					expect(
						new TransportTimeClass(context, "@4n").valueOf()
					).to.be.closeTo(1.0, 0.01);
					expect(
						new TransportTimeClass(context, "@1m").valueOf()
					).to.be.closeTo(2.0, 0.01);
				});
			}, 0.7);
		});
	});

	context("Operators", () => {
		it("can add the current time", () => {
			return Offline((context) => {
				const transport = context.transport;
				transport.start();
				return atTime(0.59, () => {
					const now = transport.seconds;
					const quarterNote = 60 / transport.bpm.value;
					expect(
						new TransportTimeClass(context, "+4i").valueOf()
					).to.be.closeTo(4 / transport.PPQ + now, 0.1);
					expect(
						new TransportTimeClass(context, "+2n").valueOf()
					).to.be.closeTo(quarterNote * 2 + now, 0.1);
					transport.stop();
				});
			}, 0.6);
		});
	});

	context("Conversions", () => {
		it("converts time into notation", () => {
			return Offline((context) => {
				const transport = context.transport;
				transport.bpm.value = 120;
				transport.timeSignature = 4;
				expect(TransportTime("4n").toNotation()).to.equal("4n");
				expect(TransportTime(1.5).toNotation()).to.equal("2n.");
				expect(TransportTime(0).toNotation()).to.equal("0");
				expect(TransportTime("1:0:0").toNotation()).to.equal("1m");
			});
		});

		it("converts time into samples", () => {
			return Offline((context) => {
				expect(TransportTime(2).toSamples()).to.equal(
					2 * context.sampleRate
				);
			});
		});

		it("converts time into frequency", () => {
			return Offline(() => {
				expect(TransportTime(2).toFrequency()).to.equal(0.5);
			});
		});

		it("converts time into seconds", () => {
			return Offline(() => {
				expect(TransportTime("2n").toSeconds()).to.equal(1);
			});
		});

		it("converts time into BarsBeatsSixteenths", () => {
			return Offline(() => {
				expect(TransportTime("3:1:3").toBarsBeatsSixteenths()).to.equal(
					"3:1:3"
				);
				expect(TransportTime(2).toBarsBeatsSixteenths()).to.equal(
					"1:0:0"
				);
			});
		});
	});
});

import { getContext } from "../Global.js";
import { Seconds, Ticks } from "../type/Units.js";
import { isDefined } from "../util/TypeCheck.js";
import { TimeClass } from "./Time.js";
import { TimeBaseUnit, TimeExpression, TimeValue } from "./TimeBase.js";

/**
 * TransportTime is a time along the Transport's
 * timeline. It is similar to Tone.Time, but instead of evaluating
 * against the AudioContext's clock, it is evaluated against
 * the Transport's position. See [TransportTime wiki](https://github.com/Tonejs/Tone.js/wiki/TransportTime).
 * @category Unit
 */
export class TransportTimeClass<
	Type extends Seconds | Ticks = Seconds,
> extends TimeClass<Type> {
	readonly name: string = "TransportTime";

	/**
	 * Return the current time in whichever context is relevant
	 */
	protected _now(): Type {
		return this.context.transport.seconds as Type;
	}

	/**
	 * Return the time in ticks.
	 */
	toTicks(): Ticks {
		if (isDefined(this._val)) {
			return super.toTicks();
		}
		// read the transport's actual current tick instead of re-deriving it
		// from elapsed seconds at the current bpm, which ignores tempo changes.
		// round up to the next tick since the current one may already be
		// in the middle of being processed by the clock.
		const transport = this.context.transport;
		return Math.ceil(transport.getTicksAtTime(transport.now()));
	}

	protected _getExpressions(): TimeExpression<Type> {
		const expressions = super._getExpressions();
		// Override the quantize ("@") handler so that it returns Transport time
		// instead of AudioContext time.
		expressions.quantize = {
			method: (capture: string): Type => {
				const quantTo = new TimeClass(this.context, capture).valueOf();
				const nextSubdivisionAudioTime =
					this.context.transport.nextSubdivision(quantTo);
				return this._secondsToUnits(
					this.context.transport.getSecondsAtTime(
						nextSubdivisionAudioTime
					)
				);
			},
			regexp: /^@(.+)/,
		};
		return expressions;
	}
}

/**
 * TransportTime is a time along the Transport's
 * timeline. It is similar to Tone.Time, but instead of evaluating
 * against the AudioContext's clock, it is evaluated against
 * the Transport's position. See [TransportTime wiki](https://github.com/Tonejs/Tone.js/wiki/TransportTime).
 * @category Unit
 */
export function TransportTime(
	value?: TimeValue,
	units?: TimeBaseUnit
): TransportTimeClass {
	return new TransportTimeClass(getContext(), value, units);
}

export * from "./NoteUnits.js";

import { Note } from "./NoteUnits.js";

/**
 * A number representing a time in seconds
 * @category Unit
 */
export type Seconds = number;

/**
 * A number used to measure the intensity of a sound on a logarithmic scale.
 * @category Unit
 */
export type Decibels = number;

/**
 * A number that is between [0, 1]
 * @category Unit
 */
export type NormalRange = number;

/**
 * A number that is between [-1, 1]
 * @category Unit
 */
export type AudioRange = number;

/**
 * Half-step note increments, i.e. 12 is an octave above the root. and 1 is a half-step up.
 * @category Unit
 */
export type Interval = number;

/**
 * A number representing the multiplication factor applied to a signal
 * @category Unit
 */
export type GainFactor = number;

/**
 * A number greater than or equal to 0.
 * @category Unit
 */
export type Positive = number;

/**
 * Represents a subdivision of a measure.
 * The number represents the subdivision. "t" represents a triplet. A "." add a half.
 * e.g. "4n" is a quarter note, "4t" is a quarter note triplet, and "4n." is a dotted quarter note.
 * @category Unit
 */
export type Subdivision =
	| "1m"
	| "1n"
	| "1n."
	| `${2 | 4 | 8 | 16 | 32 | 64 | 128 | 256}${"n" | "n." | "t"}`
	| "0";
/**
 * A time object has a subdivision as the keys and a number as the values.
 * @example
 * Tone.Time({
 * 	"2n": 1,
 * 	"8n": 3
 * }).valueOf(); // 2n + 8n * 3
 * @category Unit
 */
export type TimeObject = {
	[sub in Subdivision]?: number;
};

/**
 * Time can be described in a number of ways. Read more [Time](https://github.com/Tonejs/Tone.js/wiki/Time).
 * * Numbers, which will be taken literally as the time (in seconds).
 * * Notation, ("4n", "8t") describes time in BPM and time signature relative values.
 * * TransportTime, ("4:3:2") will also provide tempo and time signature relative times in the form BARS:QUARTERS:SIXTEENTHS.
 * * Frequency, ("8hz") is converted to the length of the cycle in seconds.
 * * Now-Relative, ("+1") prefix any of the above with "+" and it will be interpreted as "the current time plus whatever expression follows".
 * * Object, ({"4n" : 3, "8t" : -1}). The resulting time is equal to the sum of all of the keys multiplied by the values in the object.
 * * No Argument, for methods which accept time, no argument will be interpreted as "now" (i.e. the currentTime).
 * @category Unit
 */
export type Time = string | Seconds | TimeObject | Subdivision;

/**
 * Frequency can be described similar to time, except ultimately the
 * values are converted to frequency instead of seconds. A number
 * is taken literally as the value in hertz. Additionally any of the
 * Time encodings can be used. Note names in the form
 * of NOTE OCTAVE (i.e. C4) are also accepted and converted to their
 * frequency value.
 * @category Unit
 */
export type Frequency = Subdivision | Note | string | Hertz;

/**
 *
 * @category Unit
 */
export type TimeSignature = number | number[];

/**
 * TransportTime describes a position along the Transport's timeline. It is
 * similar to Time in that it uses all the same encodings, but TransportTime specifically
 * pertains to the Transport's timeline, which is startable, stoppable, loopable, and seekable.
 * [Read more](https://github.com/Tonejs/Tone.js/wiki/TransportTime)
 * @category Unit
 */
export type TransportTime = Time;

/**
 * Ticks are the basic subunit of the Transport. They are
 * the smallest unit of time that the Transport supports.
 * @category Unit
 */
export type Ticks = number;

/**
 * Beats per minute
 * @category Unit
 */
export type BPM = number;

/**
 * Angle between 0 and 360.
 * @category Unit
 */
export type Degrees = number;

/**
 * Angle between 0 and 2 * PI.
 * @category Unit
 */
export type Radians = number;

/**
 * A colon-separated representation of time in the form of
 * Bars:Beats:Sixteenths.
 * @category Unit
 */
export type BarsBeatsSixteenths = `${number}:${number}:${number}`;
/**
 * Sampling is the reduction of a continuous signal to a discrete signal.
 * Audio is typically sampled 44100 times per second.
 * @category Unit
 */
export type Samples = number;

/**
 * Hertz are a frequency representation defined as one cycle per second.
 * @category Unit
 */
export type Hertz = number;

/**
 * A Cent is 1/100th of a semitone.
 * e.g. a value of 50 cents would be halfway between two intervals.
 * @category Unit
 */
export type Cents = number;

/**
 * One millisecond is a thousandth of a second.
 * @category Unit
 */
export type Milliseconds = number;

/**
 * A value which is a power of 2
 * @category Unit
 */
export type PowerOfTwo = number;

/**
 * Map the unit name to a unit value
 */
export interface UnitMap {
	number: number;
	decibels: Decibels;
	normalRange: NormalRange;
	audioRange: AudioRange;
	gain: GainFactor;
	positive: Positive;
	time: Time;
	frequency: Frequency;
	transportTime: TransportTime;
	ticks: Ticks;
	bpm: BPM;
	degrees: Degrees;
	radians: Radians;
	samples: Samples;
	hertz: Hertz;
	cents: Cents;
}

/**
 * All of the unit types
 * @category Unit
 */
export type Unit = UnitMap[keyof UnitMap];

/**
 * All of the unit names
 * @category Unit
 */
export type UnitName = keyof UnitMap;

