import type { BaseContext } from "../context/BaseContext.js";
import type { Time } from "../type/Units.js";
import { isUndef } from "./TypeCheck.js";

/**
 * Assert that the statement is true, otherwise invoke the error.
 * @param statement
 * @param error The message which is passed into an Error
 */
export function assert(statement: boolean, error: string): asserts statement {
	if (!statement) {
		throw new Error(error);
	}
}

/**
 * Make sure that the given value is within the range
 */
export function assertRange(value: number, gte: number, lte = Infinity): void {
	if (!(gte <= value && value <= lte)) {
		throw new RangeError(
			`Value must be within [${gte}, ${lte}], got: ${value}`
		);
	}
}

/**
 * Warn if the context is not running.
 */
export function assertContextRunning(context: BaseContext): void {
	// add a warning if the context is not started
	if (!context.isOffline && context.state !== "running") {
		warn(
			'The AudioContext is "suspended". Invoke Tone.start() from a user action to start the audio.'
		);
	}
}

/**
 * If it is currently inside a scheduled callback
 */
let isInsideScheduledCallback = false;
let printedScheduledWarning = false;

/**
 * Notify that the following block of code is occurring inside a Transport callback.
 */
export function enterScheduledCallback(insideCallback: boolean): void {
	isInsideScheduledCallback = insideCallback;
}

/**
 * Make sure that a time was passed into
 */
export function assertUsedScheduleTime(time?: Time): void {
	if (
		isUndef(time) &&
		isInsideScheduledCallback &&
		!printedScheduledWarning
	) {
		printedScheduledWarning = true;
		warn(
			"Schedulable methods should include the provided time argument to ensure accurate timing. See https://github.com/Tonejs/Tone.js/wiki/Accurate-Timing"
		);
	}
}

/**
 * A basic logging interface
 */
interface Logger {
	log: (args?: any[]) => void;
	warn: (args?: any[]) => void;
}

/**
 * The default logger is the console
 */
let defaultLogger: Logger = console;

/**
 * Set the logging interface
 */
export function setLogger(logger: Logger): void {
	defaultLogger = logger;
}

/**
 * Log anything
 */
export function log(...args: any[]): void {
	defaultLogger.log(...args);
}

/**
 * Warn anything
 */
export function warn(...args: any[]): void {
	defaultLogger.warn(...args);
}

import { Time } from "../type/Units.js";
import { assertRange } from "./Debug.js";

/**
 * Assert that the number is in the given range.
 */
export function range(min: number, max = Infinity) {
	const valueMap: WeakMap<any, number> = new WeakMap();
	return function (target: any, propertyKey: string | symbol) {
		Reflect.defineProperty(target, propertyKey, {
			configurable: true,
			enumerable: true,
			get: function () {
				return valueMap.get(this);
			},
			set: function (newValue: number) {
				assertRange(newValue, min, max);
				valueMap.set(this, newValue);
			},
		});
	};
}

/**
 * Convert the time to seconds and assert that the time is in between the two
 * values when being set.
 */
export function timeRange(min: number, max = Infinity) {
	const valueMap: WeakMap<any, Time> = new WeakMap();
	return function (target: any, propertyKey: string) {
		Reflect.defineProperty(target, propertyKey, {
			configurable: true,
			enumerable: true,
			get: function () {
				return valueMap.get(this);
			},
			set: function (newValue: Time) {
				assertRange(this.toSeconds(newValue), min, max);
				valueMap.set(this, newValue);
			},
		});
	};
}

import type { BaseToneOptions } from "../Tone.js";
import {
	isAudioBuffer,
	isAudioNode,
	isAudioParam,
} from "./AdvancedTypeCheck.js";
import { isDefined, isObject, isUndef } from "./TypeCheck.js";

/**
 * Some objects should not be merged
 */
function noCopy(key: string, arg: any): boolean {
	return (
		key === "value" ||
		isAudioParam(arg) ||
		isAudioNode(arg) ||
		isAudioBuffer(arg)
	);
}

export function deepMerge<T>(target: T): T;
export function deepMerge<T, U>(target: T, source1: U): T & U;
export function deepMerge<T, U, V>(
	target: T,
	source1: U,
	source2: V
): T & U & V;
export function deepMerge<T, U, V, W>(
	target: T,
	source1: U,
	source2: V,
	source3: W
): T & U & V & W;
/**
 * Recursively merge an object
 * @param target the object to merge into
 * @param sources the source objects to merge
 */
export function deepMerge(target: any, ...sources: any[]): any {
	if (!sources.length) {
		return target;
	}
	const source = sources.shift();

	if (isObject(target) && isObject(source)) {
		for (const key in source) {
			if (noCopy(key, source[key])) {
				target[key] = source[key];
			} else if (isObject(source[key])) {
				if (!target[key]) {
					Object.assign(target, { [key]: {} });
				}
				deepMerge(target[key], source[key] as any);
			} else {
				Object.assign(target, { [key]: source[key] as any });
			}
		}
	}
	// @ts-ignore
	return deepMerge(target, ...sources);
}

/**
 * Returns true if the two arrays have the same value for each of the elements
 */
export function deepEquals<T>(arrayA: T[], arrayB: T[]): boolean {
	return (
		arrayA.length === arrayB.length &&
		arrayA.every((element, index) => arrayB[index] === element)
	);
}

/**
 * Convert an args array into an object.
 * @internal
 */
export function optionsFromArguments<T extends object>(
	defaults: T,
	argsArray: IArguments,
	keys: Array<keyof T> = [],
	objKey?: keyof T
): T {
	const opts: Partial<T> = {};
	const args = Array.from(argsArray);
	// if the first argument is an object and has an object key
	if (isObject(args[0]) && objKey && !Reflect.has(args[0], objKey)) {
		// if it's not part of the defaults
		const partOfDefaults = Object.keys(args[0]).some((key) =>
			Reflect.has(defaults, key)
		);
		if (!partOfDefaults) {
			// merge that key
			deepMerge(opts, { [objKey]: args[0] });
			// remove the obj key from the keys
			keys.splice(keys.indexOf(objKey), 1);
			// shift the first argument off
			args.shift();
		}
	}
	if (args.length === 1 && isObject(args[0])) {
		deepMerge(opts, args[0]);
	} else {
		for (let i = 0; i < keys.length; i++) {
			if (isDefined(args[i])) {
				opts[keys[i]] = args[i];
			}
		}
	}
	return deepMerge(defaults, opts);
}

/**
 * Return this instances default values by calling Constructor.getDefaults()
 */
export function getDefaultsFromInstance<T>(instance: T): BaseToneOptions {
	type ToneClass = {
		constructor: ToneClass;
		getDefaults: () => BaseToneOptions;
	} & T;

	return (instance as ToneClass).constructor.getDefaults();
}

/**
 * Returns the fallback if the given object is undefined.
 * Take an array of arguments and return a formatted options object.
 * @internal
 */
export function defaultArg<T>(given: T, fallback: T): T {
	if (isUndef(given)) {
		return fallback;
	} else {
		return given;
	}
}

/**
 * Remove all of the properties belonging to omit from obj.
 */
export function omitFromObject<T extends object, O extends string[]>(
	obj: T,
	omit: O
): Omit<T, keyof O> {
	omit.forEach((prop) => {
		if (Reflect.has(obj, prop)) {
			delete obj[prop];
		}
	});
	return obj;
}

import { expect } from "chai";

import { DrawInstance } from "./Draw.js";

describe("Draw", () => {
	const originalRAF = window.requestAnimationFrame;
	before(async () => {
		window.requestAnimationFrame = (callback) => {
			return setTimeout(callback, 10);
		};
	});

	after(() => {
		window.requestAnimationFrame = originalRAF;
	});

	it("can schedule a callback at a AudioContext time", (done) => {
		const draw = new DrawInstance();
		const scheduledTime = draw.now() + 0.2;
		draw.schedule(() => {
			expect(draw.context.currentTime).to.be.closeTo(scheduledTime, 0.05);
			draw.dispose();
			done();
		}, scheduledTime);
	});

	it("can schedule multiple callbacks", (done) => {
		const draw = new DrawInstance();
		let callbackCount = 0;
		const firstEvent = draw.now() + 0.1;
		draw.schedule(() => {
			callbackCount++;
			expect(draw.context.currentTime).to.be.closeTo(firstEvent, 0.05);
		}, firstEvent);

		const thirdEvent = draw.now() + 0.3;
		draw.schedule(() => {
			callbackCount++;
			expect(draw.context.currentTime).to.be.closeTo(thirdEvent, 0.05);
			expect(callbackCount).to.equal(3);
			done();
			draw.dispose();
		}, thirdEvent);

		const secondEvent = draw.now() + 0.2;
		draw.schedule(() => {
			callbackCount++;
			expect(draw.context.currentTime).to.be.closeTo(secondEvent, 0.05);
		}, secondEvent);
	});

	it("can cancel scheduled events", (done) => {
		const draw = new DrawInstance();
		let callbackCount = 0;
		draw.schedule(() => {
			callbackCount++;
		}, draw.now() + 0.1);

		draw.schedule(() => {
			throw new Error("should not call this method");
		}, draw.now() + 0.2);

		draw.schedule(() => {
			throw new Error("should not call this method");
		}, draw.now() + 0.25);

		// cancel the second and third events
		draw.cancel(draw.now() + 0.15);

		// schedule another one after
		draw.schedule(() => {
			callbackCount++;
			expect(callbackCount).to.equal(2);
			done();
			draw.dispose();
		}, draw.now() + 0.3);
	});
});

import {
	onContextClose,
	onContextInit,
} from "../context/ContextInitialization.js";
import {
	ToneWithContext,
	ToneWithContextOptions,
} from "../context/ToneWithContext.js";
import { Seconds, Time } from "../type/Units.js";
import { Timeline, TimelineEvent } from "./Timeline.js";

interface DrawEvent extends TimelineEvent {
	callback: () => void;
}

/**
 * Draw is useful for synchronizing visuals and audio events.
 * Callbacks from Tone.Transport or any of the Tone.Event classes
 * always happen _before_ the scheduled time and are not synchronized
 * to the animation frame so they are not good for triggering tightly
 * synchronized visuals and sound. Draw makes it easy to schedule
 * callbacks using the AudioContext time and uses requestAnimationFrame.
 * @example
 * Tone.Transport.schedule((time) => {
 * 	// use the time argument to schedule a callback with Draw
 * 	Tone.Draw.schedule(() => {
 * 		// do drawing or DOM manipulation here
 * 		console.log(time);
 * 	}, time);
 * }, "+0.5");
 * Tone.Transport.start();
 * @category Core
 */
export class DrawInstance extends ToneWithContext<ToneWithContextOptions> {
	readonly name: string = "Draw";

	/**
	 * The duration after which events are not invoked.
	 */
	expiration: Seconds = 0.25;

	/**
	 * The amount of time before the scheduled time
	 * that the callback can be invoked. Default is
	 * half the time of an animation frame (0.008 seconds).
	 */
	anticipation: Seconds = 0.008;

	/**
	 * All of the events.
	 */
	private _events: Timeline<DrawEvent> = new Timeline();

	/**
	 * The draw loop
	 */
	private _boundDrawLoop = this._drawLoop.bind(this);

	/**
	 * The animation frame id
	 */
	private _animationFrame = -1;

	/**
	 * Schedule a function at the given time to be invoked
	 * on the nearest animation frame.
	 * @param  callback  Callback is invoked at the given time.
	 * @param  time      The time relative to the AudioContext time to invoke the callback.
	 * @example
	 * Tone.Transport.scheduleRepeat(time => {
	 * 	Tone.Draw.schedule(() => console.log(time), time);
	 * }, 1);
	 * Tone.Transport.start();
	 */
	schedule(callback: () => void, time: Time): this {
		this._events.add({
			callback,
			time: this.toSeconds(time),
		});
		// start the draw loop on the first event
		if (this._events.length === 1) {
			this._animationFrame = requestAnimationFrame(this._boundDrawLoop);
		}
		return this;
	}

	/**
	 * Cancel events scheduled after the given time
	 * @param  after  Time after which scheduled events will be removed from the scheduling timeline.
	 */
	cancel(after?: Time): this {
		this._events.cancel(this.toSeconds(after));
		return this;
	}

	/**
	 * The draw loop
	 */
	private _drawLoop(): void {
		const now = this.context.currentTime;
		this._events.forEachBefore(now + this.anticipation, (event) => {
			if (now - event.time <= this.expiration) {
				event.callback();
			}
			this._events.remove(event);
		});
		if (this._events.length > 0) {
			this._animationFrame = requestAnimationFrame(this._boundDrawLoop);
		}
	}

	dispose(): this {
		super.dispose();
		this._events.dispose();
		cancelAnimationFrame(this._animationFrame);
		return this;
	}
}

