		emitter.emit("something");
		emitter.emit("something-else");
	});

	it("can invoke an event once", () => {
		const emitter = new Emitter();
		emitter.once("something", (val) => {
			expect(val).to.equal(1);
		});
		emitter.emit("something", 1);
		emitter.emit("something", 2);
		emitter.dispose();
