		if (firstEvent1) {
			expect(firstEvent1.name).is.equal("C");
		}
		sched.dispose();
	});

	it("can the next event after the given time", () => {
		const sched = new Timeline<StateTimelineEvent>();
		expect(sched.getAfter(0)).is.null;
