	it("can cancel an item", () => {
		const sched = new Timeline();
		sched.add({ time: 3 });
		sched.add({ time: 5 });
		sched.add({ time: 4 });
		sched.add({ time: 8 });
		sched.add({ time: 5 });
		expect(sched.length).to.equal(5);
		sched.cancel(10);
		expect(sched.length).to.equal(5);
		sched.cancel(5);
		expect(sched.length).to.equal(2);
		sched.cancel(3);
		expect(sched.length).to.equal(0);
		sched.dispose();
	});

	it("can cancel items after the given time", () => {
