		it("iterates over all items after the given time", () => {
			const sched = new Timeline();
			sched.add({ time: 0 });
			sched.add({ time: 0.1 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.3 });
			sched.add({ time: 0.4 });
			let count = 0;
			sched.forEachAfter(0.1, (event) => {
				expect(event).to.be.an("object");
				expect(event.time).to.be.above(0.1);
				count++;
			});
			expect(count).to.equal(3);
			sched.dispose();
