			sched.add({ time: 0.2 });
			sched.add({ time: 0.3 });
			sched.add({ time: 0.4 });
			let count = 0;
			sched.forEachAfter(0.5, () => {
				count++;
			});
			expect(count).to.equal(0);
			sched.dispose();
		});

		it("handles time ranges before the first object", () => {
