			sched.add({ time: 0.1 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.3 });
			sched.add({ time: 0.4 });
			let count = 0;
			sched.forEachAfter(-Infinity, () => {
				count++;
			});
			expect(count).to.equal(4);
			sched.dispose();
		});

		it("can iterate after inclusive of the item at the given time", () => {
			const sched = new Timeline();
			sched.add({ time: 0.1 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.3 });
			sched.add({ time: 0.4 });
			let count = 0;
			sched.forEachFrom(0.2, () => {
				count++;
			});
			expect(count).to.equal(4);
			count = 0;
			sched.forEachFrom(0.21, () => {
				count++;
			});
			expect(count).to.equal(2);
			count = 0;
			sched.forEachFrom(0, () => {
				count++;
			});
			expect(count).to.equal(5);
			sched.dispose();
		});

		it("iterates over all items at the given time", () => {
			const sched = new Timeline();
			sched.add({ time: 0 });
			sched.add({ time: 0 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.2 });
			sched.add({ time: 0.4 });
			let count = 0;
			sched.forEachAtTime(0.1, (event) => {
				count++;
			});
			expect(count).to.equal(0);
			// and with an actual time
			sched.forEachAtTime(0.2, (event) => {
				expect(event.time).to.equal(0.2);
				count++;
			});
			expect(count).to.equal(2);
			sched.dispose();
		});

		it("can remove items during iterations", () => {
			const sched = new Timeline();
			for (let i = 0; i < 1000; i++) {
				sched.add({ time: i });
