			sched.forEach((event) => {
				sched.remove(event);
			});
			expect(sched.length).to.equal(0);
			sched.dispose();
		});

		it("can add items during iteration", () => {
			interface AddedInterface {
				time: number;
				added?: boolean;
			}
			const sched = new Timeline<AddedInterface>();
			for (let i = 0; i < 1000; i++) {
				sched.add({ time: i });
			}
			let added = false;
			sched.forEach((event) => {
