describe("AutoFilter", () => {
	BasicTests(AutoFilter);
	EffectTests(AutoFilter);

	it("matches a file", () => {
		return CompareToFile(
			() => {
				const autoFilter = new AutoFilter({
					baseFrequency: 200,
					octaves: 4,
					frequency: 4,
					type: "sine",
				}).toDestination();
				new Noise().connect(autoFilter).start();
				autoFilter.start(0.2);
			},
			"autoFilter.wav",
			0.1
		);
	});

	context("API", () => {
		it("can pass in options in the constructor", () => {
			const autoFilter = new AutoFilter({
				baseFrequency: 2000,
				octaves: 2,
				type: "sawtooth",
			});
			expect(autoFilter.baseFrequency).to.be.closeTo(2000, 0.1);
			expect(autoFilter.octaves).to.equal(2);
			expect(autoFilter.type).to.equal("sawtooth");
			autoFilter.dispose();
		});

		it("can be started and stopped", () => {
			const autoFilter = new AutoFilter();
			autoFilter.start().stop("+0.2");
			autoFilter.dispose();
		});

		it("can get/set the options", () => {
			const autoFilter = new AutoFilter();
			autoFilter.set({
				baseFrequency: 1200,
				frequency: 2.4,
				type: "triangle",
			});
			expect(autoFilter.get().baseFrequency).to.be.closeTo(1200, 0.01);
			expect(autoFilter.get().frequency).to.be.closeTo(2.4, 0.01);
			expect(autoFilter.get().type).to.equal("triangle");
			autoFilter.dispose();
		});

		it("can set the frequency and depth", () => {
			const autoFilter = new AutoFilter();
			autoFilter.depth.value = 0.4;
			autoFilter.frequency.value = 0.4;
			expect(autoFilter.depth.value).to.be.closeTo(0.4, 0.01);
			expect(autoFilter.frequency.value).to.be.closeTo(0.4, 0.01);
			autoFilter.dispose();
		});

		it("can set the filter options", () => {
			const autoFilter = new AutoFilter();
			autoFilter.filter.Q.value = 2;
			expect(autoFilter.filter.Q.value).to.be.closeTo(2, 0.01);
			autoFilter.dispose();
		});

		it("accepts baseFrequency and octaves as frequency values", () => {
			const autoFilter = new AutoFilter("2n", "C2", 4);
			expect(autoFilter.baseFrequency).to.be.closeTo(
				Note.freq("C2") as number,
				0.01
			);
			expect(autoFilter.octaves).to.equal(4);
			autoFilter.dispose();
		});

		it("can sync the frequency to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const autoFilter = new AutoFilter(2);
				autoFilter.sync();
				autoFilter.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				// transport.start(0)
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(4, 0.1);
		});

		it("can unsync the frequency to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const autoFilter = new AutoFilter(2);
				autoFilter.sync();
				autoFilter.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				autoFilter.unsync();
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(2, 0.1);
		});
	});
});

import { Filter, FilterOptions } from "../component/filter/Filter.js";
import { Frequency, Positive } from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { SourceOptions } from "../source/Source.js";
import { LFOEffect, LFOEffectOptions } from "./LFOEffect.js";

export interface AutoFilterOptions extends LFOEffectOptions {
	baseFrequency: Frequency;
	octaves: Positive;
	filter: Omit<
		FilterOptions,
		keyof SourceOptions | "frequency" | "detune" | "gain"
	>;
}

/**
 * AutoFilter is a Tone.Filter with a Tone.LFO connected to the filter cutoff frequency.
 * Setting the LFO rate and depth allows for control over the filter modulation rate
 * and depth.
 *
 * @example
 * // create an autofilter and start its LFO
 * const autoFilter = new Tone.AutoFilter("4n").toDestination().start();
 * // route an oscillator through the filter and start it
 * const oscillator = new Tone.Oscillator().connect(autoFilter).start();
 * @category Effect
 */
export class AutoFilter extends LFOEffect<AutoFilterOptions> {
	readonly name: string = "AutoFilter";

	/**
	 * The filter node
	 */
	readonly filter: Filter;

	/**
	 * The octaves placeholder
	 */
	private _octaves!: Positive;

	/**
	 * @param frequency The rate of the LFO.
	 * @param baseFrequency The lower value of the LFOs oscillation
	 * @param octaves The number of octaves above the baseFrequency
	 */
	constructor(
		frequency?: Frequency,
		baseFrequency?: Frequency,
		octaves?: Positive
	);
	constructor(options?: Partial<AutoFilterOptions>);
	constructor() {
		const options = optionsFromArguments(
			AutoFilter.getDefaults(),
			arguments,
			["frequency", "baseFrequency", "octaves"]
		);
		super(options);

		this.filter = new Filter(
			Object.assign(options.filter, {
				context: this.context,
			})
		);

		// connections
		this.connectEffect(this.filter);
		this._lfo.connect(this.filter.frequency);
		this.octaves = options.octaves;
		this.baseFrequency = options.baseFrequency;
	}

	static getDefaults(): AutoFilterOptions {
		return Object.assign(LFOEffect.getDefaults(), {
			baseFrequency: 200,
			octaves: 2.6,
			filter: {
				type: "lowpass" as const,
				rolloff: -12 as -12,
				Q: 1,
			},
		});
	}

	/**
	 * The minimum value of the filter's cutoff frequency.
	 */
	get baseFrequency(): Frequency {
		return this._lfo.min;
	}
	set baseFrequency(freq) {
		this._lfo.min = this.toFrequency(freq);
		// and set the max
		this.octaves = this._octaves;
	}

	/**
	 * The maximum value of the filter's cutoff frequency.
	 */
	get octaves(): Positive {
		return this._octaves;
	}
	set octaves(oct) {
		this._octaves = oct;
		this._lfo.max = this._lfo.min * Math.pow(2, oct);
	}

	dispose(): this {
		super.dispose();
		this.filter.dispose();
		return this;
	}
}

