			const autoPanner = new AutoPanner();
			autoPanner.depth.value = 0.4;
			autoPanner.frequency.value = 0.4;
			expect(autoPanner.depth.value).to.be.closeTo(0.4, 0.01);
			expect(autoPanner.frequency.value).to.be.closeTo(0.4, 0.01);
			autoPanner.dispose();
		});

		it("can sync the frequency to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const panner = new AutoPanner(2);
				panner.sync();
				panner.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				// transport.start(0)
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(4, 0.1);
		});

		it("can unsync the frequency to the transport", async () => {
			const buffer = await Offline(({ transport }) => {
				const panner = new AutoPanner(2);
				panner.sync();
				panner.frequency.toDestination();
				transport.bpm.setValueAtTime(transport.bpm.value * 2, 0.05);
				panner.unsync();
				// transport.start(0)
			}, 0.1);
			expect(buffer.getValueAtTime(0)).to.be.closeTo(2, 0.1);
			expect(buffer.getValueAtTime(0.05)).to.be.closeTo(2, 0.1);
		});
	});
});

import { Panner } from "../component/channel/Panner.js";
import { Frequency } from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { LFOEffect, LFOEffectOptions } from "./LFOEffect.js";

export interface AutoPannerOptions extends LFOEffectOptions {
	channelCount: number;
}

/**
 * AutoPanner is a {@link Panner} with an {@link LFO} connected to the pan amount.
 * [Related Reading](https://www.ableton.com/en/blog/autopan-chopper-effect-and-more-liveschool/).
 *
 * @example
 * // create an autopanner and start it
 * const autoPanner = new Tone.AutoPanner("4n").toDestination().start();
 * // route an oscillator through the panner and start it
 * const oscillator = new Tone.Oscillator().connect(autoPanner).start();
 * @category Effect
 */
export class AutoPanner extends LFOEffect<AutoPannerOptions> {
	readonly name: string = "AutoPanner";

	/**
	 * The filter node
	 */
	readonly _panner: Panner;

	/**
	 * @param frequency Rate of left-right oscillation.
	 */
	constructor(frequency?: Frequency);
	constructor(options?: Partial<AutoPannerOptions>);
	constructor() {
		const options = optionsFromArguments(
			AutoPanner.getDefaults(),
			arguments,
			["frequency"]
		);
		super(options);

		this._panner = new Panner({
			context: this.context,
			channelCount: options.channelCount,
		});
		// connections
		this.connectEffect(this._panner);
		this._lfo.connect(this._panner.pan);
		this._lfo.min = -1;
		this._lfo.max = 1;
	}

	static getDefaults(): AutoPannerOptions {
		return Object.assign(LFOEffect.getDefaults(), {
			channelCount: 1,
		});
	}

	dispose(): this {
		super.dispose();
		this._panner.dispose();
		return this;
	}
}

