import { Gain } from "../core/context/Gain.js";
import { Param } from "../core/context/Param.js";
import { connectSeries } from "../core/context/ToneAudioNode.js";
import { NormalRange, Seconds, Time } from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import {
	ToneAudioWorklet,
	ToneAudioWorkletOptions,
} from "../core/worklet/ToneAudioWorklet.js";
import { EffectOptions } from "./Effect.js";
import { Effect } from "./Effect.js";
import { workletName } from "./ReverseDelay.worklet.js";

export interface ReverseDelayOptions extends EffectOptions {
	delayTime: Time;
	feedback: NormalRange;
}

/**
 * A feedback delay effect that plays the echos in reverse.
 * Algorithm and gain function found in [this pdf](https://ccrma.stanford.edu/~jingjiez/portfolio/echoing-harmonics/pdfs/A%20Pitch%20Shifting%20Reverse%20Echo%20Audio%20Effect.pdf)
 *
 * @example
 * const reverse = new Tone.ReverseDelay(1.5, 0.75).toDestination();
 * const synth = new Tone.Synth().connect(reverse);
 * synth.triggerAttackRelease("C4", "2n");
 * @category Effect
 */
export class ReverseDelay extends Effect<ReverseDelayOptions> {
	readonly name: string = "ReverseDelay";

	/**
	 * The node that does the reverse delay effect.
	 */
	private _reverseDelayWorklet: ReverseDelayWorklet;

	/**
	 * @param delayTime The amount of time the incoming signal will be delayed and reversed.
	 * @param feedback The amount of signal which is fed back through the delay.
	 */
	constructor(delayTime?: Time, feedback?: NormalRange);
	constructor(options?: Partial<ReverseDelayOptions>);
	constructor() {
		const options = optionsFromArguments(
			ReverseDelay.getDefaults(),
			arguments,
			["delayTime", "feedback"]
		);
		super(options);

		this._reverseDelayWorklet = this._connectWorklet(
			options.delayTime,
			options.feedback
		);
	}

	private _connectWorklet(
		delayTime: Time,
		feedback: NormalRange
	): ReverseDelayWorklet {
		const worklet = new ReverseDelayWorklet({
			context: this.context,
			delayTime: this.toSeconds(delayTime),
			feedback,
		});
		this.connectEffect(worklet);

		return worklet;
	}

	/**
	 * The amount of time the incoming signal is delayed and reversed
	 */
	get delayTime(): Time {
		return this._reverseDelayWorklet.delayTime;
	}

	set delayTime(delayTime) {
		const prev = this._reverseDelayWorklet;
		this._reverseDelayWorklet = this._connectWorklet(
			delayTime,
			this.feedback
		);

		// Prevent sudden stop when disposing previous worklet
		prev.output.gain.linearRampTo(0, this.toSeconds(this.delayTime));
		this.context.setTimeout(
			() => prev.dispose(),
			this.toSeconds(this.delayTime)
		);
	}

	/**
	 * The amount of signal which is fed back through the delay.
	 */
	get feedback(): NormalRange {
		return this._reverseDelayWorklet.feedback.value;
	}

	set feedback(feedback) {
		this._reverseDelayWorklet.set({ feedback });
	}

	static getDefaults(): ReverseDelayOptions {
		return Object.assign(Effect.getDefaults(), {
			wet: 0.5,
			delayTime: 1,
			feedback: 0.5,
		});
	}

	dispose(): this {
		super.dispose();
		this._reverseDelayWorklet.dispose();
		return this;
	}
}

export interface ReverseDelayWorkletOptions extends ToneAudioWorkletOptions {
	delayTime: Seconds;
	feedback: NormalRange;
}

/**
 * Internal class which creates an AudioWorklet to reverse the delay signal
 */
class ReverseDelayWorklet extends ToneAudioWorklet<ReverseDelayWorkletOptions> {
	readonly name: string = "ReverseDelayWorklet";

	readonly input: Gain;
	readonly output: Gain;

	readonly delayTime: Seconds;
	readonly feedback: Param<"normalRange">;

	constructor(options?: Partial<ReverseDelayOptions>);
	constructor() {
		const options = optionsFromArguments(
			ReverseDelayWorklet.getDefaults(),
			arguments,
			["delayTime", "feedback"]
		);

		super({
			...options,
			workletOptions: {
				processorOptions: {
					delayTime: options.delayTime,
				},
			},
		});

		this.input = new Gain({ context: this.context });
		this.output = new Gain({ context: this.context });

		this.delayTime = options.delayTime;
		this.feedback = new Param<"normalRange">({
			context: this.context,
			value: options.feedback,
			units: "normalRange",
			param: this._dummyParam,
			swappable: true,
			minValue: 0,
			maxValue: 0.9999,
		});
	}

	static getDefaults(): ReverseDelayWorkletOptions {
		return Object.assign(ToneAudioWorklet.getDefaults(), {
			delayTime: 1,
			feedback: 0.5,
		});
	}

	protected _audioWorkletName(): string {
		return workletName;
	}

	onReady(node: AudioWorkletNode): void {
		connectSeries(this.input, node, this.output);
		const feedback = node.parameters.get("feedback") as AudioParam;
		this.feedback.setParam(feedback);
	}

	dispose(): this {
		super.dispose();
		this.input.dispose();
		this.output.dispose();
		this.feedback.dispose();
		return this;
	}
}

import "../core/worklet/SingleIOProcessor.worklet.js";
import "../core/worklet/DelayLine.worklet.js";

import { registerProcessor } from "../core/worklet/WorkletGlobalScope.js";

export const workletName = "reverse-delay";

export const reverseDelayWorklet = /* javascript */ `
	class ReverseDelayWorklet extends SingleIOProcessor {

		constructor(options) {
			super(options);
			this.delayTime = Math.floor(this.sampleRate * options.processorOptions.delayTime);
			const channels = options.channelCount || 2;
			this.delayLine = new DelayLine(this.delayTime * 2, channels);
		}

		static get parameterDescriptors() {
			return [{
				name: "feedback",
				defaultValue: 0.5,
				minValue: 0,
				maxValue: 0.9999,
				automationRate: "k-rate"
			}];
		}

		generate(input, channel, parameters) {
			const reversedSample = this.delayLine.getReverse(channel, this.delayTime);
			const delayedSample = this.delayLine.get(channel, this.delayTime);

			// Push the forward sample back on the line
			this.delayLine.push(channel, input + delayedSample * parameters.feedback);

			// Play the reversed sample
			return reversedSample;
		}
	}
`;

registerProcessor(workletName, reverseDelayWorklet);

import { CrossFade } from "../component/channel/CrossFade.js";
import { Merge } from "../component/channel/Merge.js";
import { Split } from "../component/channel/Split.js";
import { Gain } from "../core/context/Gain.js";
import {
	connect,
	connectSeries,
	OutputNode,
	ToneAudioNode,
} from "../core/context/ToneAudioNode.js";
import { readOnly } from "../core/util/Interface.js";
import { Signal } from "../signal/Signal.js";
import { EffectOptions } from "./Effect.js";

export type StereoEffectOptions = EffectOptions;

/**
 * Base class for Stereo effects.
 */
export class StereoEffect<
	Options extends StereoEffectOptions,
> extends ToneAudioNode<Options> {
	readonly name: string = "StereoEffect";

	readonly input: Gain;
	readonly output: CrossFade;

	/**
	 * the drywet knob to control the amount of effect
	 */
	private _dryWet: CrossFade;

	/**
	 * The wet control, i.e. how much of the effected
	 * will pass through to the output.
	 */
	readonly wet: Signal<"normalRange">;

	/**
	 * Split it
	 */
	protected _split: Split;

	/**
	 * the stereo effect merger
	 */
	protected _merge: Merge;

	constructor(options: StereoEffectOptions) {
		super(options);

		this.input = new Gain({ context: this.context });
		// force mono sources to be stereo
		this.input.channelCount = 2;
		this.input.channelCountMode = "explicit";

		this._dryWet = this.output = new CrossFade({
			context: this.context,
			fade: options.wet,
		});
		this.wet = this._dryWet.fade;
		this._split = new Split({ context: this.context, channels: 2 });
		this._merge = new Merge({ context: this.context, channels: 2 });

		// connections
		this.input.connect(this._split);
		// dry wet connections
		this.input.connect(this._dryWet.a);
		this._merge.connect(this._dryWet.b);
		readOnly(this, ["wet"]);
	}

	/**
	 * Connect the left part of the effect
	 */
	protected connectEffectLeft(...nodes: OutputNode[]): void {
		this._split.connect(nodes[0], 0, 0);
		connectSeries(...nodes);
		connect(nodes[nodes.length - 1], this._merge, 0, 0);
	}

	/**
	 * Connect the right part of the effect
	 */
	protected connectEffectRight(...nodes: OutputNode[]): void {
		this._split.connect(nodes[0], 1, 0);
		connectSeries(...nodes);
		connect(nodes[nodes.length - 1], this._merge, 0, 1);
	}

	static getDefaults(): StereoEffectOptions {
		return Object.assign(ToneAudioNode.getDefaults(), {
			wet: 1,
		});
	}

	dispose(): this {
		super.dispose();
		this._dryWet.dispose();
		this._split.dispose();
		this._merge.dispose();
		return this;
	}
}

import { Merge } from "../component/channel/Merge.js";
import { Split } from "../component/channel/Split.js";
import { Gain } from "../core/context/Gain.js";
import { NormalRange } from "../core/type/Units.js";
import { readOnly } from "../core/util/Interface.js";
import { Signal } from "../signal/Signal.js";
import { StereoEffect, StereoEffectOptions } from "./StereoEffect.js";

export interface StereoFeedbackEffectOptions extends StereoEffectOptions {
	feedback: NormalRange;
}

/**
 * Base class for stereo feedback effects where the effectReturn is fed back into the same channel.
 */
export class StereoFeedbackEffect<
	Options extends StereoFeedbackEffectOptions,
> extends StereoEffect<Options> {
	/**
	 * The amount of feedback from the output
	 * back into the input of the effect (routed
	 * across left and right channels).
	 */
	readonly feedback: Signal<"normalRange">;

	/**
	 * the left side feedback
	 */
	protected _feedbackL: Gain;

	/**
	 * the right side feedback
	 */
	protected _feedbackR: Gain;

	/**
	 * Split the channels for feedback
	 */
	protected _feedbackSplit: Split;

	/**
	 * Merge the channels for feedback
	 */
	protected _feedbackMerge: Merge;

	constructor(options: StereoFeedbackEffectOptions) {
		super(options);

		this.feedback = new Signal({
			context: this.context,
			value: options.feedback,
			units: "normalRange",
		});
		this._feedbackL = new Gain({ context: this.context });
		this._feedbackR = new Gain({ context: this.context });

		this._feedbackSplit = new Split({ context: this.context, channels: 2 });
		this._feedbackMerge = new Merge({ context: this.context, channels: 2 });

		this._merge.connect(this._feedbackSplit);
		this._feedbackMerge.connect(this._split);

		// the left output connected to the left input
		this._feedbackSplit.connect(this._feedbackL, 0, 0);
		this._feedbackL.connect(this._feedbackMerge, 0, 0);

		// the right output connected to the right input
		this._feedbackSplit.connect(this._feedbackR, 1, 0);
		this._feedbackR.connect(this._feedbackMerge, 0, 1);

		// the feedback control
		this.feedback.fan(this._feedbackL.gain, this._feedbackR.gain);
		readOnly(this, ["feedback"]);
	}

	static getDefaults(): StereoFeedbackEffectOptions {
		return Object.assign(StereoEffect.getDefaults(), {
			feedback: 0.5,
		});
	}

	dispose(): this {
		super.dispose();
		this.feedback.dispose();
		this._feedbackL.dispose();
		this._feedbackR.dispose();
		this._feedbackSplit.dispose();
		this._feedbackMerge.dispose();
		return this;
	}
}

