import { expect } from "chai";

import { BasicTests } from "../../test/helper/Basic.js";
import {
	atTime,
	holdClock,
	Offline,
	whenBetween,
} from "../../test/helper/Offline.js";
import { Time } from "../core/type/Time.js";
import { noOp } from "../core/util/Interface.js";
import { Loop } from "./Loop.js";

describe("Loop", () => {
	BasicTests(Loop);

	context("Constructor", () => {
		it("takes a callback and an interval", () => {
			return Offline(() => {
				const callback = noOp;
				const loop = new Loop(callback, "8n");
				expect(loop.callback).to.equal(callback);
				expect(loop.interval).to.equal(Time("8n").valueOf());
				loop.dispose();
			});
		});

		it("can be constructed with no arguments", () => {
			return Offline(() => {
				const loop = new Loop();
				expect(loop.iterations).to.equal(Infinity);
				loop.dispose();
			});
		});

		it("can pass in arguments in options object", () => {
			return Offline(() => {
				const callback = noOp;
				const loop = new Loop({
					callback: callback,
					iterations: 4,
					probability: 0.3,
					interval: "8t",
				});
				expect(loop.callback).to.equal(callback);
				expect(loop.interval.valueOf()).to.equal(Time("8t").valueOf());
				expect(loop.iterations).to.equal(4);
				expect(loop.probability).to.equal(0.3);
				loop.dispose();
			});
		});
	});

	context("Get/Set", () => {
		it("can set values with object", () => {
			return Offline(() => {
				const callback = noOp;
				const loop = new Loop();
				loop.set({
					callback: callback,
					iterations: 8,
				});
				expect(loop.callback).to.equal(callback);
				expect(loop.iterations).to.equal(8);
				loop.dispose();
			});
		});

		it("can get/set the humanize and interval values", () => {
			return Offline(() => {
				const loop = new Loop();
				loop.humanize = true;
				loop.interval = 0.4;
				expect(loop.humanize).to.be.true;
				expect(loop.interval).to.be.closeTo(0.4, 0.002);
				loop.dispose();
			});
		});

		it("can set get a the values as an object", () => {
			return Offline(() => {
				const callback = noOp;
				const loop = new Loop({
					callback: callback,
					iterations: 4,
					probability: 0.3,
				});
				const values = loop.get();
				expect(values.iterations).to.equal(4);
				expect(values.probability).to.equal(0.3);
				loop.dispose();
			});
		});
	});

	context("Callback", () => {
		it("does not invoke get invoked until started", () => {
			return Offline(({ transport }) => {
				new Loop(() => {
					throw new Error("shouldn't call this callback");
				}, "8n");
				transport.start();
			}, 0.3);
		});

		it("is invoked after it's started", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				const loop = new Loop(() => {
					invoked = true;
					loop.dispose();
				}, 0.05).start(0);
				transport.start();
			});
			expect(invoked).to.be.true;
		});

		it("passes in the scheduled time to the callback", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				const now = transport.now() + 0.1;
				const loop = new Loop((time) => {
					expect(time).to.be.a("number");
					expect(time - now).to.be.closeTo(0.3, 0.01);
					loop.dispose();
					invoked = true;
				});
				transport.start(now);
				loop.start(0.3);
			}, 0.5);
			expect(invoked).to.be.true;
		});

		it("can mute the callback", () => {
			return Offline(({ transport }) => {
				const loop = new Loop(() => {
					throw new Error("shouldn't call this callback");
				}, "4n").start();
				loop.mute = true;
				expect(loop.mute).to.be.true;
				transport.start();
			}, 0.4);
		});

		it("can trigger with some probability", () => {
			return Offline(({ transport }) => {
				const loop = new Loop(() => {
					throw new Error("shouldn't call this callback");
				}, "4n").start();
				loop.probability = 0;
				expect(loop.probability).to.equal(0);
				transport.start();
			}, 0.4);
		});
	});

	context("Scheduling", () => {
		it("can be started and stopped multiple times", () => {
			return Offline(({ transport }) => {
				const loop = new Loop().start().stop(0.2).start(0.4);
				transport.start(0);
				return (time) => {
					whenBetween(time, 0, 0.19, () => {
						expect(loop.state).to.equal("started");
					});
					whenBetween(time, 0.2, 0.39, () => {
						expect(loop.state).to.equal("stopped");
					});
					whenBetween(time, 0.4, Infinity, () => {
						expect(loop.state).to.equal("started");
					});
				};
			}, 0.6);
		});

		it("restarts when transport is restarted", () => {
			return Offline(({ transport }) => {
				const note = new Loop().start(0).stop(0.4);
				transport.start(0).stop(0.5).start(0.55);
				return (time) => {
					whenBetween(time, 0, 0.39, () => {
						expect(note.state).to.equal("started");
					});
					whenBetween(time, 0.4, 0.5, () => {
						expect(note.state).to.equal("stopped");
					});
					whenBetween(time, 0.55, 0.8, () => {
						expect(note.state).to.equal("started");
					});
				};
			}, 1);
		});

		it("can be cancelled", () => {
			return Offline(({ transport }) => {
				const note = new Loop().start(0);
				expect(note.state).to.equal("started");
				transport.start();

				let firstStop = false;
				let restarted = false;
				const tested = false;
				return (time) => {
					// stop the transport
					if (time > 0.2 && !firstStop) {
						firstStop = true;
						transport.stop();
						note.cancel();
					}
					if (time > 0.3 && !restarted) {
						restarted = true;
						transport.start();
					}
					if (time > 0.4 && !tested) {
						restarted = true;
						transport.start();
						expect(note.state).to.equal("stopped");
					}
				};
			}, 0.5);
		});
	});

	context("Looping", () => {
		it("starts a Loop created between stop() and start() with the new run (#1502)", async () => {
			const beats: number[] = [];
			let restartTime = 0;
			await Offline((context) => {
				const transport = context.transport;
				transport.start(0);
				return atTime(
					0.02,
					holdClock(transport, (time) => {
						transport.stop(time);
						new Loop({
							context,
							callback: (t) => beats.push(t),
							interval: "4i",
						}).start(0);
						restartTime = time + 0.005;
						transport.start(restartTime);
					})
				);
			}, 0.05);
			expect(beats[0]).to.be.at.least(restartTime);
		});

		it("loops", async () => {
			let callCount = 0;
			await Offline(({ transport }) => {
				new Loop({
					interval: 0.1,
					callback: () => {
						callCount++;
					},
				}).start(0);
				transport.start();
			}, 0.81);
			expect(callCount).to.equal(9);
		});

		it("loops for the specified interval", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				let lastCall;
				new Loop({
					interval: "8n",
					callback: (time) => {
						if (lastCall) {
							invoked = true;
							expect(time - lastCall).to.be.closeTo(0.25, 0.01);
						}
						lastCall = time;
					},
				}).start(0);
				transport.start();
			}, 1);
			expect(invoked).to.be.true;
		});

		it("can loop a specific number of iterations", async () => {
			let callCount = 0;
			await Offline(({ transport }) => {
				new Loop({
					interval: 0.1,
					iterations: 2,
					callback: () => {
						callCount++;
					},
				}).start(0);
				transport.start();
			}, 0.4);
			expect(callCount).to.equal(2);
		});

		it("reports the progress of the loop", async () => {
			await Offline(({ transport }) => {
				const loop = new Loop({
					interval: 1,
				}).start(0);
				transport.start();
				return (time) => {
					expect(loop.progress).to.be.closeTo(time, 0.05);
				};
			}, 0.8);
		});
	});

	context("playbackRate", () => {
		it("can adjust the playbackRate", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				let lastCall;
				const loop = new Loop({
					playbackRate: 2,
					interval: 0.5,
					callback: (time) => {
						if (lastCall) {
							invoked = true;
							expect(time - lastCall).to.be.closeTo(0.25, 0.01);
						}
						lastCall = time;
					},
				}).start(0);
				expect(loop.playbackRate).to.equal(2);
				transport.start();
			}, 0.7);
			expect(invoked).to.be.true;
		});

		it("can playback at a faster rate", async () => {
			let callCount = 0;
			await Offline(({ transport }) => {
				const loop = new Loop({
					interval: 0.1,
					callback: () => {
						callCount++;
					},
				}).start(0);
				loop.playbackRate = 1.5;
				expect(loop.playbackRate).to.equal(1.5);
				transport.start();
			}, 0.81);
			expect(callCount).to.equal(13);
		});
	});
});

import {
	ToneWithContext,
	ToneWithContextOptions,
} from "../core/context/ToneWithContext.js";
import {
	NormalRange,
	Positive,
	Seconds,
	Time,
	TransportTime,
} from "../core/type/Units.js";
import { optionsFromArguments } from "../core/util/Defaults.js";
import { noOp } from "../core/util/Interface.js";
import { BasicPlaybackState } from "../core/util/StateTimeline.js";
import { ToneEvent } from "./ToneEvent.js";

export interface LoopOptions extends ToneWithContextOptions {
	callback: (time: Seconds) => void;
	interval: Time;
	playbackRate: Positive;
	iterations: number;
	probability: NormalRange;
	mute: boolean;
	humanize: boolean | Time;
}

/**
 * Loop creates a looped callback at the
 * specified interval. The callback can be
 * started, stopped and scheduled along
 * the Transport's timeline.
 * @example
 * const loop = new Tone.Loop((time) => {
 * 	// triggered every eighth note.
 * 	console.log(time);
 * }, "8n").start(0);
 * Tone.Transport.start();
 * @category Event
 */
export class Loop<
	Options extends LoopOptions = LoopOptions,
> extends ToneWithContext<Options> {
	readonly name: string = "Loop";

	/**
	 * The event which produces the callbacks
	 */
	private _event: ToneEvent;

	/**
	 * The callback to invoke with the next event in the pattern
	 */
	callback: (time: Seconds) => void;

	/**
	 * @param callback The callback to invoke at the time.
	 * @param interval The time between successive callback calls.
	 */
	constructor(callback?: (time: Seconds) => void, interval?: Time);
	constructor(options?: Partial<LoopOptions>);
	constructor() {
		const options = optionsFromArguments(Loop.getDefaults(), arguments, [
			"callback",
			"interval",
		]);
		super(options);

		this._event = new ToneEvent({
			context: this.context,
			callback: this._tick.bind(this),
			loop: true,
			loopEnd: options.interval,
			playbackRate: options.playbackRate,
			probability: options.probability,
			humanize: options.humanize,
		});

		this.callback = options.callback;
		// set the iterations
		this.iterations = options.iterations;
	}

	static getDefaults(): LoopOptions {
		return Object.assign(ToneWithContext.getDefaults(), {
			interval: "4n",
			callback: noOp,
			playbackRate: 1,
			iterations: Infinity,
			probability: 1,
			mute: false,
			humanize: false,
		});
	}

	/**
	 * Start the loop at the specified time along the Transport's timeline.
	 * @param  time  When to start the Loop.
	 */
	start(time?: TransportTime): this {
		this._event.start(time);
		return this;
	}

	/**
	 * Stop the loop at the given time.
	 * @param  time  When to stop the Loop.
	 */
	stop(time?: TransportTime): this {
		this._event.stop(time);
		return this;
	}

	/**
	 * Cancel all scheduled events greater than or equal to the given time
	 * @param  time  The time after which events will be cancel.
	 */
	cancel(time?: TransportTime): this {
		this._event.cancel(time);
		return this;
	}

	/**
	 * Internal function called when the notes should be called
	 * @param time  The time the event occurs
	 */
	protected _tick(time: Seconds): void {
		this.callback(time);
	}

	/**
	 * The state of the Loop, either started or stopped.
	 */
	get state(): BasicPlaybackState {
		return this._event.state;
	}

	/**
	 * The progress of the loop as a value between 0-1. 0, when the loop is stopped or done iterating.
	 */
	get progress(): NormalRange {
		return this._event.progress;
	}

	/**
	 * The time between successive callbacks.
	 * @example
	 * const loop = new Tone.Loop();
	 * loop.interval = "8n"; // loop every 8n
	 */
	get interval(): Time {
		return this._event.loopEnd;
	}
	set interval(interval) {
		this._event.loopEnd = interval;
	}

	/**
	 * The playback rate of the loop. The normal playback rate is 1 (no change).
	 * A `playbackRate` of 2 would be twice as fast.
	 */
	get playbackRate(): Positive {
		return this._event.playbackRate;
	}
	set playbackRate(rate) {
		this._event.playbackRate = rate;
	}

	/**
	 * Random variation +/-0.01s to the scheduled time.
	 * Or give it a time value which it will randomize by.
	 */
	get humanize(): boolean | Time {
		return this._event.humanize;
	}
	set humanize(variation) {
		this._event.humanize = variation;
	}

	/**
	 * The probably of the callback being invoked.
	 */
	get probability(): NormalRange {
		return this._event.probability;
	}

	set probability(prob) {
		this._event.probability = prob;
	}

	/**
	 * Muting the Loop means that no callbacks are invoked.
	 */
	get mute(): boolean {
		return this._event.mute;
	}

	set mute(mute) {
		this._event.mute = mute;
	}

	/**
	 * The number of iterations of the loop. The default value is `Infinity` (loop forever).
	 */
	get iterations(): number {
		if (this._event.loop === true) {
			return Infinity;
		} else {
			return this._event.loop as number;
		}
	}
	set iterations(iters) {
		if (iters === Infinity) {
			this._event.loop = true;
		} else {
			this._event.loop = iters;
		}
	}

	dispose(): this {
		super.dispose();
		this._event.dispose();
		return this;
	}
}

import { expect } from "chai";

import { BasicTests } from "../../test/helper/Basic.js";
import { atTime, Offline } from "../../test/helper/Offline.js";
import { Time } from "../core/type/Time.js";
import { noOp } from "../core/util/Interface.js";
import { Part } from "./Part.js";
import { Sequence } from "./Sequence.js";
import { ToneEvent } from "./ToneEvent.js";

describe("Part", () => {
	BasicTests(Part);

	context("Constructor", () => {
		it("takes a callback and an array of values", async () => {
			await Offline(() => {
				const callback = noOp;
				const part = new Part(callback, [0, 1, 2]);
				expect(part.callback).to.equal(callback);
				expect(part.length).to.equal(3);
				part.dispose();
			});
		});

		it("can be constructed with no arguments", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				part.dispose();
			});
		});

		it("can pass in arguments in options object", async () => {
			await Offline(() => {
				const callback = noOp;
				const part = new Part({
					callback,
					events: [0, 1, 2],
					humanize: true,
					loop: true,
					loopEnd: "4n",
					probability: 0.3,
				});
				expect(part.callback).to.equal(callback);
				expect(part.length).to.equal(3);
				expect(part.loop).to.be.true;
				expect(part.loopEnd).to.equal(Time("4n").valueOf());
				expect(part.probability).to.equal(0.3);
				expect(part.humanize).to.be.true;
				part.dispose();
			});
		});
	});

	context("Adding / Removing / Getting Events", () => {
		it("can take events in the constructor as an array of times", async () => {
			await Offline(() => {
				const part = new Part(noOp, ["0", "8n", "4n"]);
				expect(part.length).to.equal(3);
				part.dispose();
			});
		});

		it("can take events in the constructor as an array of times and values", async () => {
			await Offline(() => {
				const part = new Part(noOp, [
					["0", "C4"],
					["8n", "D3"],
					["4n", "E4"],
				]);
				expect(part.length).to.equal(3);
				part.dispose();
			});
		});

		it("can retrieve an event using 'at'", async () => {
			await Offline(() => {
				const part = new Part(noOp, [
					["0", 0],
					["8n", "C2"],
					["4n", 2],
				]);
				expect(part.length).to.equal(3);
				expect(part.at(0)).to.be.instanceof(ToneEvent);
				expect((part.at(0) as ToneEvent).value).to.equal(0);
				expect((part.at("8n") as ToneEvent).value).to.equal("C2");
				expect((part.at("4n") as ToneEvent).value).to.equal(2);
				expect(part.at("2n")).to.be.null;
				part.dispose();
			});
		});

		it("can set the value of an existing event with 'at'", async () => {
			await Offline(() => {
				const part = new Part({
					events: [[0, "C3"]],
				});
				expect(part.length).to.equal(1);
				expect((part.at(0) as ToneEvent).value).to.equal("C3");
				part.at(0, "C4");
				expect((part.at(0) as ToneEvent).value).to.equal("C4");
				part.dispose();
			});
		});

		it("can take events in the constructor as an array of objects", async () => {
			await Offline(() => {
				const part = new Part(noOp, [
					{
						note: "C3",
						time: 0.3,
					},
					{
						note: "D3",
						time: 1,
					},
				]);
				expect(part.length).to.equal(2);
				expect((part.at(0.3) as ToneEvent).value).to.be.an("object");
				expect((part.at(0.3) as ToneEvent).value.note).to.equal("C3");
				part.dispose();
			});
		});

		it("can cancel event changes", async () => {
			let count = 0;
			await Offline(({ transport }) => {
				const part = new Part(
					(time) => {
						count++;
					},
					[
						{
							note: "C3",
							time: 0,
						},
						{
							note: "D3",
							time: 0.2,
						},
					]
				)
					.start(0)
					.stop(0.1);
				part.cancel(0.1);
				transport.start(0);
			}, 0.3);
			expect(count).to.equal(2);
		});

		it("can add an event as a time and value", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				part.add(1, "D3");
				expect(part.length).to.equal(1);
				expect((part.at(1) as ToneEvent).value).to.equal("D3");
				part.dispose();
			});
		});

		it("can add an event as an object", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				part.add({
					duration: "8n",
					note: "D4",
					time: 0.5,
				});
				expect(part.length).to.equal(1);
				expect((part.at(0.5) as ToneEvent).value).to.be.an("object");
				expect(
					(part.at(0.5) as ToneEvent).value.duration
				).to.deep.equal("8n");
				expect((part.at(0.5) as ToneEvent).value.note).to.deep.equal(
					"D4"
				);
				part.dispose();
			});
		});

		it("can add another part", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				const subPart = new Part({
					events: [0, 0.5],
				});
				part.add(0.2, subPart);
				expect(part.length).to.equal(1);
				expect(part.at(0.2)).to.equal(subPart);
				part.dispose();
			});
		});

		it("can add a sequence", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				const subPart = new Sequence({
					events: [0, 1, 2, 3],
				});
				part.add(0.2, subPart);
				expect(part.length).to.equal(1);
				expect(part.at(0.2)).to.equal(subPart);
				part.dispose();
			});
		});

		it("can remove an event by time", async () => {
			await Offline(() => {
				const part = new Part({
					events: [
						[0.2, "C3"],
						[0.2, "C4"],
					],
				});
				expect(part.length).to.equal(2);
				part.remove(0.2);
				expect(part.length).to.equal(0);
				part.dispose();
			});
		});

		it("can remove an event by time and value", async () => {
			await Offline(() => {
				const secondEvent = {
					note: "C4",
					time: 0.2,
				};
				const part = new Part({
					events: [[0.2, "C2"], secondEvent],
				});
				expect(part.length).to.equal(2);
				part.remove(0.2, "C2");
				expect(part.length).to.equal(1);
				part.remove(secondEvent);
				expect(part.length).to.equal(0);
				part.dispose();
			});
		});

		it("added events have the same settings as the parent", async () => {
			await Offline(() => {
				const part = new Part({
					events: [
						[0.2, "C3"],
						[0.3, "C4"],
					],
					loopEnd: "1m",
					loopStart: "4n",
					probability: 0.2,
				});
				part.humanize = 0.1;
				const firstEvent = part.at(0.2) as ToneEvent;
				expect(firstEvent.humanize).to.equal(0.1);
				expect(firstEvent.probability).to.equal(0.2);
				// loop duration is the same
				expect(firstEvent.loopEnd).to.equal(Time("1m").valueOf());
				expect(firstEvent.loopStart).to.equal(Time("4n").valueOf());

				const secondEvent = part.at(0.3) as ToneEvent;
				expect(secondEvent.humanize).to.equal(0.1);
				expect(secondEvent.probability).to.equal(0.2);
				// loop duration is the same
				expect(secondEvent.loopEnd).to.equal(Time("1m").valueOf());
				expect(secondEvent.loopStart).to.equal(Time("4n").valueOf());
				part.dispose();
			});
		});

		it("will create an event using at if one wasn't there at that time", async () => {
			await Offline(() => {
				const part = new Part();
				expect(part.length).to.equal(0);
				expect((part.at(0.1, "C4") as ToneEvent).value).to.equal("C4");
				expect(part.length).to.equal(1);
				part.dispose();
			});
		});

		it("can remove all of the events", async () => {
			await Offline(() => {
				const part = new Part(noOp, [0, 1, 2, 3, 4, 5]);
				expect(part.length).to.equal(6);
				part.clear();
				expect(part.length).to.equal(0);
				part.dispose();
			});
		});
	});

	context("Part callback", () => {
		it("does not invoke get invoked until started", async () => {
			await Offline(({ transport }) => {
				const part = new Part(() => {
					throw new Error("shouldn't call this callback");
				}, [0, 0.4]);
				transport.start();
			}, 0.5);
		});

		it("is invoked after it's started", async () => {
			let invocations = 0;
			await Offline(({ transport }) => {
				const part = new Part(() => {
					invocations++;
				}, [0, 0.1]).start(0);
				transport.start();
			}, 0.2);
			expect(invocations).to.equal(2);
		});

		it("passes in the scheduled time to the callback", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				const startTime = 0.1;
				const part = new Part(
					(time) => {
						expect(time).to.be.a("number");
						expect(time - startTime).to.be.closeTo(0.5, 0.01);
						invoked = true;
					},
					[0.3]
				);
				part.start(0.2);
				transport.start(startTime);
			}, 0.62);
			expect(invoked).to.be.true;
		});

		it("passes in the value to the callback", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				const part = new Part(
					(time, thing) => {
						expect(time).to.be.a("number");
						expect(thing).to.equal("thing");
						part.dispose();
						invoked = true;
					},
					[[0, "thing"]]
				).start();
				transport.start();
			}, 0.6);
			expect(invoked).to.be.true;
		});

		it("can mute the callback", async () => {
			await Offline(({ transport }) => {
				const part = new Part(() => {
					throw new Error("shouldn't call this callback");
				}, [0, 0.1, 0.2, 0.3]).start();
				part.mute = true;
				expect(part.mute).to.be.true;
				transport.start();
			}, 0.5);
		});

		it("can trigger with some probability", async () => {
			await Offline(({ transport }) => {
				const part = new Part(() => {
					throw new Error("shouldn't call this callback");
				}, [0, 0.1, 0.2, 0.3]).start();
				part.probability = 0;
				expect(part.probability).to.equal(0);
				transport.start();
			}, 0.4);
		});

		it("invokes all of the scheduled events", async () => {
			let count = 0;
			await Offline(({ transport }) => {
				new Part(() => {
					count++;
				}, [0, 0.1, 0.2, 0.3]).start();
				transport.start();
			}, 0.4);
			expect(count).to.equal(4);
		});

		it("invokes all of the scheduled events at the correct times", async () => {
			let count = 0;
			await Offline(({ transport }) => {
				const now = transport.now() + 0.1;
				new Part(
					(time, value) => {
						count++;
						expect(time - now).to.be.closeTo(value, 0.01);
					},
					[
						[0, 0],
						[0.1, 0.1],
						[0.2, 0.2],
					]
				).start();
				transport.start(now);
			}, 0.4);
			expect(count).to.equal(3);
		});

		it("starts an event added after the part was started", async () => {
			let invoked = false;
			await Offline(({ transport }) => {
				const part = new Part({
					events: [[0, 0]],
					loop: true,
					loopEnd: 0.2,
					callback(time, value): void {
						if (value === 1) {
							invoked = true;
						}
					},
				}).start(0);
				transport.start();
				return atTime(0.1, () => {
					part.add(0.1, 1);
				});
			}, 0.6);
			expect(invoked).to.be.true;
		});

		it("can schedule a subpart", async () => {
			let invocations = 0;
			await Offline(({ transport }) => {
				const startTime = 0.1;
				const subPart = new Part({
					events: [
						[0, 1],
						[0.3, 2],
					],
				});
				const part = new Part((time, value) => {
					invocations++;
					if (value === 0) {
						expect(time - startTime).to.be.closeTo(0, 0.01);
					} else if (value === 1) {
						expect(time - startTime).to.be.closeTo(0.2, 0.01);
					} else if (value === 2) {
						expect(time - startTime).to.be.closeTo(0.5, 0.01);
						part.dispose();
					}
				})
					.add(0.2, subPart)
					.add(0, 0)
					.start(0);
				transport.start(startTime);
			}, 0.7);
